m_actionList.scriptText:
import java.io.*;
import org.json.*;
try {
  String app = "{fg_app_name}";
  String day = "{dayofmonth}";
  new File("/storage/emulated/0/MacroDroid/Claude").mkdirs();
  File f = new File("/storage/emulated/0/MacroDroid/Claude/st.json");
  JSONObject o = new JSONObject();
  if (f.exists()) {
    try {
      BufferedReader r = new BufferedReader(new InputStreamReader(new FileInputStream(f), "UTF-8"));
      StringBuilder sb = new StringBuilder();
      String line;
      while ((line = r.readLine()) != null) sb.append(line);
      r.close();
      o = new JSONObject(sb.toString());
    } catch (Exception e2) {
      o = new JSONObject();
    }
  }
  if (!day.equals(o.optString("d")) || o.optJSONObject("m") == null) {
    o = new JSONObject();
    o.put("d", day);
    o.put("m", new JSONObject());
  }
  JSONObject m = o.getJSONObject("m");
  if (app == null) app = "";
  app = app.trim();
  if (app.length() == 0) app = "?";
  if (app.length() > 40) app = app.substring(0, 40);
  m.put(app, m.optInt(app, 0) + 1);
  Writer w = new OutputStreamWriter(new FileOutputStream(f), "UTF-8");
  w.write(o.toString());
  w.close();
  return "ok";
} catch (Exception e) {
  return "err";
}
